


/* ********************* بروز کردن تعطیلات ********************* */



/* ********************* آخر هفته ها **************======= */
UPDATE T_INS_DATES d
SET IS_HOLIDAY =
        CASE

            WHEN d.IS_WEEKEND = 1 THEN 1

            /* ===================== تعطیلات شمسی ===================== */
            WHEN (d.PERSIAN_MONTH = 1  AND d.PERSIAN_DAY IN (1, 2, 3, 4)) THEN 1
            WHEN (d.PERSIAN_MONTH = 1  AND d.PERSIAN_DAY = 12) THEN 1
            WHEN (d.PERSIAN_MONTH = 1  AND d.PERSIAN_DAY = 13) THEN 1
            WHEN (d.PERSIAN_MONTH = 3  AND d.PERSIAN_DAY IN (14, 15)) THEN 1
            WHEN (d.PERSIAN_MONTH = 11 AND d.PERSIAN_DAY = 22) THEN 1
            WHEN (d.PERSIAN_MONTH = 12 AND d.PERSIAN_DAY IN (29, 30)) THEN 1

            /* ===================== تعطیلات هجری ===================== */
            -- محرم
            WHEN (d.HIJRI_MONTH = 1  AND d.HIJRI_DAY IN (9, 10)) THEN 1

            -- صفر: اربعین، 28 صفر
            WHEN (d.HIJRI_MONTH = 2  AND d.HIJRI_DAY IN (20, 28)) THEN 1

            -- صفر: آخر ماه (شهادت امام رضا)
            WHEN (
                d.HIJRI_MONTH = 2
                    AND d.HIJRI_DAY = (
                    SELECT MAX(d2.HIJRI_DAY)
                    FROM T_INS_DATES d2
                    WHERE d2.HIJRI_YEAR  = d.HIJRI_YEAR
                      AND d2.HIJRI_MONTH = 2
                )
                ) THEN 1

            -- ربیع الاول
            WHEN (d.HIJRI_MONTH = 3  AND d.HIJRI_DAY IN (8, 17)) THEN 1

            -- جمادی الثانی
            WHEN (d.HIJRI_MONTH = 6  AND d.HIJRI_DAY = 3) THEN 1

            -- رجب
            WHEN (d.HIJRI_MONTH = 7  AND d.HIJRI_DAY IN (13, 27)) THEN 1

            -- شعبان
            WHEN (d.HIJRI_MONTH = 8  AND d.HIJRI_DAY = 15) THEN 1

            -- رمضان
            WHEN (d.HIJRI_MONTH = 9  AND d.HIJRI_DAY = 21) THEN 1

            -- شوال
            WHEN (d.HIJRI_MONTH = 10 AND d.HIJRI_DAY IN (1, 2, 25)) THEN 1

            -- ذیحجه
            WHEN (d.HIJRI_MONTH = 12 AND d.HIJRI_DAY IN (10, 18)) THEN 1

            /* ===================== سایر روزها ===================== */
            ELSE 0
            END;
